#include <cstdio>
#include <vector>
#include <algorithm>
using namespace std;
const long long MOD_A=1000000007,MOD_B=998244353;
const int maxk=7,base=1000000;
long long n_value;
long long order_counter;
int total_answer;
int prefix_sum_arr[maxk];
vector<int> seqs_arr[maxk];

void create_sequences(int x,int length){
    order_counter++, seqs_arr[length].push_back(((order_counter - x) % MOD_B + MOD_B) % MOD_B);
    prefix_sum_arr[length]=(prefix_sum_arr[length]+seqs_arr[length].back())%MOD_A;
    if(length==6) return;
    for(int d=0; d<=9; d++)
        create_sequences(x*10+d,length+1);
}

void process_value(long long x){
    if(x>n_value) return;
    if(x*base+base-1<=n_value && x*base*10>n_value){
        long long current_order=order_counter;
        for(int i=0,mult=1;i<=6;i++,mult*=10){
            int sz=seqs_arr[i].size();
            int diff=((current_order - x*mult) % MOD_B + MOD_B) % MOD_B;
            int pos=lower_bound(seqs_arr[i].begin(),seqs_arr[i].end(),MOD_B - diff)-seqs_arr[i].begin();
            total_answer=(total_answer+1LL*diff*sz+prefix_sum_arr[i])%MOD_A;
            total_answer=(total_answer-1LL*MOD_A*(sz - pos)%MOD_A+MOD_A)%MOD_A;
            order_counter+=sz;
        }
        return;
    }
    order_counter++, total_answer=(total_answer+((order_counter - x) % MOD_B + MOD_B) % MOD_B)%MOD_A;
    for(int d=0; d<=9; d++)
        process_value(x*10+d);
}

int main(){
    scanf("%lld",&n_value);
    order_counter=0; create_sequences(0,0);
    for(int i=0;i<=6;i++) sort(seqs_arr[i].begin(),seqs_arr[i].end());
    order_counter=0;
    for(int i=1;i<=9;i++) process_value(i);
    printf("%d\n",total_answer);
    return 0;
}
